// Generates packages/browser-extension/page-toolkit-content.js from the
// createPageToolkit factory in background.js.
//
// Why: the page-toolkit frame executor injects the factory source with
// (0, eval)(...) inside each frame's isolated world. Frames whose CSP bans
// unsafe-eval (Claude artifact frames, other sandboxed embeds) reject that,
// so the toolkit could never run there. chrome.scripting `files` injection is
// not subject to page CSP — this generated file installs the factory as a
// global the executor prefers over eval.
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

const backgroundPath = fileURLToPath(new URL("../packages/browser-extension/background.js", import.meta.url));
const outPath = fileURLToPath(new URL("../packages/browser-extension/page-toolkit-content.js", import.meta.url));

const source = await readFile(backgroundPath, "utf8");
const marker = "\nconst createPageToolkit = ";
const start = source.indexOf(marker);
if (start < 0) throw new Error("createPageToolkit declaration not found in background.js");
const exprStart = start + marker.length;
const endMarker = "\n};";
const end = source.indexOf(endMarker, exprStart);
if (end < 0) throw new Error("createPageToolkit end anchor not found in background.js");
const factorySource = source.slice(exprStart, end + endMarker.length).trim().replace(/;$/, "");

// Parse-validate the extracted expression so a drifted end anchor fails the
// build instead of shipping a broken content script.
new Function(`return (${factorySource});`);

const banner = [
	"// GENERATED by scripts/build-page-toolkit-content.mjs from background.js — do not edit.",
	"// Installed via chrome.scripting `files` injection so CSP-strict frames",
	"// (which block eval in the isolated world) can still run the page toolkit.",
	"",
].join("\n");
await writeFile(outPath, `${banner}globalThis.__onhandPageToolkitFactory = ${factorySource};\n`, "utf8");
console.log(`page-toolkit-content.js generated (${factorySource.length} chars of factory source)`);
